SourceCode.Declaration:
/// <summary>
/// Same device-identity fields HSMobileOpsSignInRequest already carries - deliberately, so
/// HSMobileOpsDevice::registerSignIn's own upsert can be called identically from either call
/// site. Sent at launch time, before any worker has signed in, which is why there is no
/// UserName/SiteId/WarehouseId here the way signIn's own registerDevice call has - those three
/// stay blank on this call and are filled in properly the first time a worker actually signs in.
/// </summary>
[DataContractAttribute]
class HSMobileOpsRegisterDeviceRequest
{
    DataAreaId dataAreaId;
    str        deviceId;
    str        deviceBrand;
    str        deviceModel;
    str        platform;
    str        platformVersion;
    str        appVersionName;

}

Method.Source:
[DataMemberAttribute('DataAreaId')]
public DataAreaId parmDataAreaId(DataAreaId _value = dataAreaId)
{
    dataAreaId = _value;
    return dataAreaId;
}

[DataMemberAttribute('DeviceId')]
public str parmDeviceId(str _value = deviceId)
{
    deviceId = _value;
    return deviceId;
}

[DataMemberAttribute('DeviceBrand')]
public str parmDeviceBrand(str _value = deviceBrand)
{
    deviceBrand = _value;
    return deviceBrand;
}

[DataMemberAttribute('DeviceModel')]
public str parmDeviceModel(str _value = deviceModel)
{
    deviceModel = _value;
    return deviceModel;
}

[DataMemberAttribute('Platform')]
public str parmPlatform(str _value = platform)
{
    platform = _value;
    return platform;
}

[DataMemberAttribute('PlatformVersion')]
public str parmPlatformVersion(str _value = platformVersion)
{
    platformVersion = _value;
    return platformVersion;
}

[DataMemberAttribute('AppVersionName')]
public str parmAppVersionName(str _value = appVersionName)
{
    appVersionName = _value;
    return appVersionName;
}
